public void insert()
{
    next insert();

    boolean isPickedCases;
    METSalesInvoiceDPContext context = METSalesInvoiceDPContext::current();

    if (context)
    {
        if (context.custInvoiceTrans.METPickedCases != 0)
        {
            this.metInsertPickedCaseLine(this, context.custInvoiceTrans, context.salesLine, context.custInvoiceTrans.METPickedCases, false);
            isPickedCases = true;
        }

        if (context.custInvoiceTrans.METPickedBrokenCases != 0)
        {
            this.metInsertPickedCaseLine(this, context.custInvoiceTrans, context.salesLine, context.custInvoiceTrans.METPickedBrokenCases, true);
            isPickedCases = true;
        }
        if (isPickedCases)
        {
            this.selectForUpdate(true);
            this.delete();
        }

        context.dispose();
    }
}

private void metInsertPickedCaseLine(SalesInvoiceTmp     _salesInvoiceTmpBase,
                                 CustInvoiceTrans    _custInvoiceTrans,
                                 SalesLine           _salesLine,
                                 METCase             _qty,
                                 boolean             _isBrokenCase)
{
    SalesInvoiceTmp caseLine;

    EcoResProduct product;
    RecId         caseUom;
    RecId         eaUom;

    Qty          pickedCases;
    Qty          pickedBrokenCases;
    Qty          brokenQtyInCaseUnit;
    Qty          currentQtyInCaseUnit;
    Qty          totalPickedQtyInCaseUnit;

    real         allocationFactor;

    // Copy all fields from base line - carries over ItemId, description,
    // prices, charges, tax groups, and all other mapped fields.
    caseLine.data(_salesInvoiceTmpBase);

    // Clear RecId to force a new insert rather than updating existing record.
    caseLine.RecId = 0;

    product = EcoResProduct::findByProductNumber(_salesLine.ItemId);
    caseUom = UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit);
    eaUom   = UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach);

    pickedCases       = _custInvoiceTrans.METPickedCases;
    pickedBrokenCases = _custInvoiceTrans.METPickedBrokenCases;

    // Convert broken EA quantity back to sales-line unit/case unit.
    if (pickedBrokenCases && product.RecId && caseUom && eaUom)
    {
        brokenQtyInCaseUnit = UnitOfMeasureConverter::convert(
                            pickedBrokenCases,
                            eaUom,
                            caseUom,
                            NoYes::No,
                            product.RecId,
                            NoYes::No);
    }
    else
    {
        brokenQtyInCaseUnit = 0;
    }

    // Total supplied quantity in the same unit as the original sales line.
    totalPickedQtyInCaseUnit = pickedCases + brokenQtyInCaseUnit;

    if (_isBrokenCase)
    {
        // --- Broken cases line overrides - Bug 351188 ---

        // Qty Supplied = picked broken cases value. 
        caseLine.Qty = _qty;

        // UOM = EA for broken case line.
        caseLine.SalesUnitTxt = METConstants::unitEach;

        // Current line quantity in case unit for amount/GST allocation.
        currentQtyInCaseUnit = brokenQtyInCaseUnit;

        if (totalPickedQtyInCaseUnit)
        {
            allocationFactor = currentQtyInCaseUnit / totalPickedQtyInCaseUnit;
        }
        else
        {
            allocationFactor = 0;
        }

        if (currentQtyInCaseUnit > 0)
        {
            // CHANGE:
            // Cost and LUC for broken line should be based on broken quantity converted to case unit.
            //caseLine.METCost = _salesInvoiceTmpBase.METCost * currentQtyInCaseUnit;

            // Update the inserted caseLine, not the base line, because base line is deleted later.
            caseLine.METLucInclGST = abs(_salesInvoiceTmpBase.metcaseCost * currentQtyInCaseUnit);

            caseLine.METGSTTotal = abs(_salesInvoiceTmpBase.METGSTTotal * allocationFactor);
        }
        else
        {
            caseLine.METCost       = 0;
            caseLine.METLucInclGST = 0;
            caseLine.METGSTTotal   = 0;
        }

        if (caseLine.SalesUnitTxt != METConstants::unitEach)
        {
            // Qty Ordered = 0 for broken case/Not EA line.
            caseLine.METOrderedQty = 0;
        }
    }
    else
    {
        // --- Picked cases line overrides - Bug 351188 ---

        // Qty Supplied = picked cases value. 
        caseLine.Qty = _qty;

        // Qty Ordered = original sales order quantity.
        caseLine.METOrderedQty = _salesLine.SalesQty;

        // UOM = original sales order/invoice unit. outer6
        caseLine.SalesUnitTxt = _custInvoiceTrans.SalesUnit;

        currentQtyInCaseUnit = caseLine.Qty;

        if (totalPickedQtyInCaseUnit)
        {
            allocationFactor = currentQtyInCaseUnit / totalPickedQtyInCaseUnit;
        }
        else
        {
            allocationFactor = 0;
        }

        // This part was already conceptually correct.
        caseLine.METLucInclGST = abs(_salesInvoiceTmpBase.metcaseCost * caseLine.Qty);

        caseLine.METGSTTotal = abs(_salesInvoiceTmpBase.METGSTTotal * allocationFactor);
    }

    ttsbegin;
    caseLine.doInsert();
    ttscommit;
}
